    // Publications: publications, text with quotes.
    'publications.noPeerIsConnectedSo2': 'Kein Peer ist verbunden, daher kann „Von Peers abrufen“ fehlende Inhalte nicht holen. Verbinden Sie sich über {peers} mit einem.',
    'publications.thisIsACorrelationOf2': 'Dies ist eine Zuordnung unabhängig erfasster Tatsachen über eine ausdrückliche anchorId — kein Urteil. Die vollständige Aufschlüsselung nach Beobachtung für dieselbe anchorId finden Sie oben unter „Historische Nachweise zu Bitcoin-Ankern“.',
    'publications.thisIsAReadOnly': 'Dies ist ein schreibgeschützter Blick auf die Datei oben — er ändert nichts am weiter oben auf dieser Seite angezeigten Beobachtungsarchiv. Nutzen Sie oben „Archiv importieren“, wenn dieses Archiv es ersetzen soll.',
    'publications.whatReplacingTheCurrentArchive': 'Was das Ersetzen des aktuellen Archivs durch das externe Archiv oben ändern würde — das aktuelle Archiv bleibt genau so, wie es ist, bis unten ausdrücklich auf „Aktuelles Archiv ersetzen“ geklickt wird.',
    'publications.replacingRestampsEveryFactIn': 'Das Ersetzen kennzeichnet jede Tatsache im externen Archiv oben neu als IMPORTIERT (0.8.83) — der resultierende aktuelle Fingerabdruck unterscheidet sich daher vom oben angezeigten „Externer Fingerabdruck“, obwohl die zugrunde liegenden Beobachtungen identisch sind.',
    'publications.localFactsWereObservedBy': 'Lokale Tatsachen wurden von diesem Replikat direkt beobachtet. Importierte Tatsachen sind über einen früheren Import mit „Aktuelles Archiv ersetzen“ in dieses Archiv gelangt. Keine ist vertrauenswürdiger als die andere — dies gibt nur an, woher jede Tatsache stammt.',
    'publications.anExplicitDurableRecordThat2': 'Ein ausdrücklicher, dauerhafter Datensatz, dass eine Veröffentlichung auf eine andere verweist — nie aus übereinstimmenden Inhalten, Zeitstempeln oder Autoren abgeleitet. Beide Veröffentlichungen müssen oben bereits eine dauerhafte Identität haben; ein Verweis ist nie eine Einstufung als „Fork“, nur eine schlichte, zuordenbare Tatsache: Diese Veröffentlichung zeigt auf jene.',
    'publications.nothingHereIsSavedAnywhere': 'Nichts hiervon wird irgendwo gespeichert. Diese Konfiguration existiert nur im Speicher dieser Seite für diese Browsersitzung und wird verworfen, sobald die Seite neu geladen oder auf „Konfiguration löschen“ geklickt wird.',
    'publications.thisReplicaDoesNotCurrently': 'Dieses Replikat besitzt derzeit keinen gültigen Snapshot. Wählen Sie unten eine Quelle — „Snapshot importieren“, das eigene „Snapshot materialisieren“ einer Platzierung oder „Snapshot von Peer holen“ eines Peers —, um es erneut zu versuchen.',

    // Publications: leaderboardHubView, text with quotes.
    'leaderboardHubView.aBadgePresentationOfThe': 'Eine Darstellung der Erfolge als Abzeichen, die dieser Herausgeber bereits erzielt hat, über alle Veröffentlichungen, die er ausdrücklich beansprucht hat — nie ein neuer Erfolg und nie eine Punktzahl, ein Rang oder ein Bestenlisteneintrag. Manche Erfolge (die aus Verweisen abgeleiteten) haben noch keine Abzeichendarstellung und erscheinen nur in der Karte „Erfolgsprofil des Herausgebers“ oben.',

    // Publications: publisherLeaderboardSnapshotClaimAuthoringView, text with quotes.
    'publisherLeaderboardSnapshotClaimAuthoringView.authorAndExportASigned': 'Erstellen und exportieren Sie einen signierten Anspruch über den aktuellen Bestenlisten-Snapshot IHRES EIGENEN Replikats — genau das Nachweisartefakt, das das Feld „Nachweis eines Peers“ im Abgleichsarbeitsbereich von einem Peer verlangt. Erzeugen, Signieren und Exportieren sind drei getrennte, ausdrückliche Aktionen; nichts auf dieser Seite läuft automatisch.',
    'publisherLeaderboardSnapshotClaimAuthoringView.pasteThisIntoAPeer': 'Fügen Sie dies in das Feld „Nachweis eines Peers“ im Abgleichsarbeitsbereich eines Peers ein oder senden Sie ihm die heruntergeladene Datei.',

    // Publications: reconciliationCandidateLeaderboardView, text with quotes.
    'reconciliationCandidateLeaderboardView.noPeerArchiveSuppliedYet': 'Noch kein Peer-Archiv angegeben — jede Zahl unten ist Nur Quelle, bis Sie eines einfügen. Fügen Sie das eigene exportierte Archiv des Replikats eines Peers ein (Archiv exportieren, auf der Seite Veröffentlichungen) und klicken Sie auf „Als Peer-Archiv verwenden“.',

    // Publications: reconciliationWorkspaceView, text with quotes.
    'reconciliationWorkspaceView.reconcileThisReplicaSOwn': 'Gleichen Sie das eigene lokale Archiv dieses Replikats ausdrücklich mit einem einzelnen Nachweis eines Peers ab. Nichts auf dieser Seite läuft automatisch — der Abgleich findet nur statt, wenn Sie unten auf „Abgleichen“ klicken.',

